import{_ as s,o as n,c as i,a4 as t}from"./chunks/framework.B-wJupoK.js";const e="/assets/image-20250704224029475.Bq4UUi32.png",r="/assets/image-20250704225828058.BerE6WDw.png",l="/assets/image-20250704230027670.aDbzVZXi.png",p="/assets/image-20250704230126968.DX5H9m5_.png",o="/assets/image-20250704231004529.BV8qLgf0.png",h="/assets/image-20250704231204184.b2Nqjcu4.png",d="/assets/image-20250704231252815.ryz923p1.png",c="/assets/image-20250704231633897.DUSi94I6.png",g="/assets/image-20250704231717506.CkJyJg0M.png",k="/assets/image-20250705141417241.D5FkBl_a.png",u="/assets/image-20250705141856595.COE_yA0Y.png",m="/assets/image-20250705142201794.CSi7GGJJ.png",b="/assets/image-20250611211811768.AjWr7Ss_.png",C=JSON.parse('{"title":"第五款 HarmonyOS 上架作品 奇趣故事匣 来了","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/第五款 HarmonyOS 上架作品 奇趣故事匣 来了/第五款 HarmonyOS 上架作品 奇趣故事匣 来了.md","filePath":"鸿蒙开发技巧/第五款 HarmonyOS 上架作品 奇趣故事匣 来了/第五款 HarmonyOS 上架作品 奇趣故事匣 来了.md","lastUpdated":1756109794000,"__rawMarkdown":"#  第五款 HarmonyOS 上架作品 奇趣故事匣 来了\\n\\n## 前言\\n\\n北京时间2025年7月4日 ，青蓝逐码组织第五款鸿蒙元服务 **奇趣故事匣** 也发布上架了，**奇趣故事匣** 是一个奇幻故事类的应用，目前包含的核心功能有 奇趣故事分类、浏览、语音播报，还包括有华为静默登录，它也是我们[青蓝逐码](https://www.qinglanzhuma.cn/)组织的一个小伙伴独立开发前端+后端的作品，耗时一个多月的业余时间完成🎉。 \\n\\n\\n\\n## 效果一览\\n\\n![image-20250704224029475](assets/image-20250704224029475.png)\\n\\n## 开发故事\\n\\n这次作品是一个小伙伴独立完成开发并且上架的，作战能力很强，这里我们可以分享下他开发的历程故事。\\n\\n### 建立作品选型\\n\\n我们在立项前也会简单的做个技术沟通，确保目标和方向是正确并且可行的。\\n\\n![image-20250704225828058](assets/image-20250704225828058.png)\\n\\n---\\n\\n### 技术方案讨论\\n\\n如果小伙伴不懂后端，但是执行力强，还可以推荐具体的技术，如端云\\n\\n![image-20250704230027670](assets/image-20250704230027670.png)\\n\\n---\\n\\n### 程序员的思维 - 记账类APP\\n\\n传统的记账类太多，很容易引起生理反感\\n\\n![image-20250704230126968](assets/image-20250704230126968.png)\\n\\n### 接入了华为的AI朗读\\n\\n![image-20250704231004529](assets/image-20250704231004529.png)\\n\\n### 在商讨后期接入大模型，可以让用户自己AI创作故事\\n\\n![image-20250704231204184](assets/image-20250704231204184.png)\\n\\n### 思想的碰撞会指引出具体的行动方向\\n\\n![image-20250704231252815](assets/image-20250704231252815.png)\\n\\n---\\n\\n### 头脑乱掉了，简单的业务给限制住了 \\n\\n![image-20250704231633897](assets/image-20250704231633897.png)\\n\\n---\\n\\n### 实践得真知\\n\\n![image-20250704231717506](assets/image-20250704231717506.png)\\n\\n\\n\\n## 开发日志\\n\\n独立开发就是快，自己一个人噌噌噌的写和改。\\n\\n![image-20250705141417241](assets/image-20250705141417241.png)\\n\\n## 上架历程\\n\\n从提测到真正真正上架，也花了有差不多小半个月时间了\\n\\n![image-20250705141856595](assets/image-20250705141856595.png)\\n\\n## 技术说明文档\\n\\n### 项目概述\\n\\n**奇趣故事匣**是一款基于HarmonyOS开发的故事阅读应用，采用原子化服务(Atomic Service)架构。应用提供故事浏览、分类查看、在线阅读、收藏管理、阅读历史等功能，支持华为账号授权登录。\\n\\n#### 基本信息\\n- **应用名称**: 奇趣故事匣\\n- **应用类型**: 原子化服务 (atomicService)\\n- **版本**: 1.0.0 (versionCode: 1000000)\\n- **兼容SDK版本**: 5.0.4(16)\\n- **运行系统**: HarmonyOS\\n\\n### 技术架构\\n\\n#### 开发框架\\n- **开发语言**: ArkTS (TypeScript扩展)\\n- **UI框架**: ArkUI\\n- **架构模式**: Stage模型\\n- **组件化**: ComponentV2 + @Local状态管理\\n- **数据持久化**: PersistenceV2\\n- **导航**: Navigation + NavPathStack\\n\\n#### 项目结构\\n\\n```\\nFunStoryBox/\\n├── AppScope/                    ## 应用级配置\\n│   ├── app.json5               ## 应用配置文件\\n│   └── resources/              ## 应用级资源\\n├── entry/                      ## 主模块\\n│   ├── src/main/\\n│   │   ├── ets/                ## TypeScript源码\\n│   │   │   ├── components/     ## 可复用组件\\n│   │   │   ├── constants/      ## 常量定义\\n│   │   │   ├── entryability/   ## 应用入口\\n│   │   │   ├── models/         ## 数据模型\\n│   │   │   ├── pages/          ## 页面组件\\n│   │   │   └── utils/          ## 工具类\\n│   │   ├── module.json5        ## 模块配置\\n│   │   └── resources/          ## 资源文件\\n│   └── build-profile.json5     ## 构建配置\\n├── config/                     ## 签名证书配置\\n└── build-profile.json5         ## 项目构建配置\\n```\\n\\n### 核心功能模块\\n\\n#### 1. 用户认证模块\\n- **华为账号授权登录**: 集成华为账号Kit，支持OAuth2.0授权流程\\n- **自动登录**: 应用前台时自动检测登录状态\\n- **用户信息管理**: 持久化存储用户基本信息\\n\\n#### 2. 故事内容模块\\n- **故事浏览**: 支持分类浏览、热门推荐、最新更新\\n- **故事详情**: 展示故事基本信息、章节列表、相关推荐\\n- **在线阅读**: 章节内容阅读，支持阅读进度记录\\n- **搜索功能**: 故事标题和内容搜索\\n\\n#### 3. 个人中心模块\\n- **阅读历史**: 记录和管理用户阅读记录\\n- **收藏管理**: 故事收藏和取消收藏\\n- **个人信息**: 用户资料展示和管理\\n\\n#### 4. 数据管理模块\\n- **网络请求**: 封装HTTP工具类，支持GET/POST/DELETE请求\\n- **数据模型**: 定义完整的业务数据结构\\n- **状态管理**: 使用@Local和PersistenceV2管理应用状态\\n\\n### 主要页面说明\\n\\n#### 页面路由配置\\n应用使用Navigation组件进行页面管理，路由配置如下：\\n\\n| 页面名称 | 文件路径 | 功能描述 |\\n|---------|----------|----------|\\n| Layout | pages/Layout.ets | 主布局页面，包含底部导航 |\\n| StoryDetail | pages/StoryDetail.ets | 故事详情页面 |\\n| ReadStory | pages/ReadStory.ets | 故事阅读页面 |\\n| RecommendList | pages/RecommendList.ets | 推荐列表页面 |\\n| CategoryDetail | pages/CategoryDetail.ets | 分类详情页面 |\\n| SearchStory | pages/SearchStory.ets | 故事搜索页面 |\\n| AuthorDetail | pages/AuthorDetail.ets | 作者详情页面 |\\n| ReadHistory | pages/ReadHistory.ets | 阅读历史页面 |\\n| FavoriteStory | pages/FavoriteStory.ets | 收藏故事页面 |\\n\\n#### 核心页面架构\\n\\n##### 1. 主布局页面 (Layout.ets)\\n- 底部Tab导航，包含：首页、发现、我的\\n- 使用Tabs组件实现页面切换\\n- 集成用户信息状态管理\\n\\n##### 2. 首页 (Home.ets)\\n- 分类统计展示\\n- 热门故事推荐\\n- 最新故事列表\\n- 最近阅读记录\\n- 下拉刷新功能\\n\\n##### 3. 发现页面 (Discover.ets)\\n- 故事分类浏览\\n- 推荐内容展示\\n\\n##### 4. 个人中心 (Mine.ets)\\n- 用户信息展示\\n- 阅读历史入口\\n- 收藏管理入口\\n\\n### 技术特性\\n\\n#### 1. 组件化开发\\n- **可复用组件**: PageHeader、SectionTitle、StoryCard、StoryList\\n- **组件通信**: 使用@Local装饰器实现组件间状态共享\\n- **生命周期管理**: 合理使用aboutToAppear等生命周期方法\\n\\n#### 2. 状态管理\\n- **全局状态**: 使用AppStorageV2管理导航栈\\n- **持久化状态**: 使用PersistenceV2存储用户信息\\n- **响应式更新**: @Monitor装饰器监听状态变化\\n\\n#### 3. 网络通信\\n- **HTTP封装**: 统一的网络请求工具类\\n- **错误处理**: 完善的网络错误处理机制\\n- **数据格式**: 支持JSON和form-urlencoded格式\\n\\n#### 4. 安全特性\\n- **应用签名**: 配置开发和发布环境的签名证书\\n- **权限管理**: 申请网络访问权限\\n- **数据加密**: 集成RSA加密工具\\n\\n### API接口设计\\n\\n#### 基础配置\\n- **服务器地址**: https://ad.qqgsj.lzzvx.com\\n- **超时时间**: 60秒\\n- **请求格式**: JSON / form-urlencoded\\n\\n#### 主要接口\\n\\n| 接口类型 | 接口路径 | 功能描述 |\\n|---------|----------|----------|\\n| GET | /api/category/totalStoriesCount | 获取分类故事统计 |\\n| GET | /api/story/hot | 获取热门故事 |\\n| GET | /api/story/latest | 获取最新故事 |\\n| GET | /api/story/search | 故事搜索 |\\n| POST | /api/user/authorizeLogin | 华为账号授权登录 |\\n| GET | /api/user/read/history/latest | 获取最近阅读记录 |\\n| POST | /api/favorite/add | 添加收藏 |\\n| DELETE | /api/favorite | 取消收藏 |\\n\\n### 数据模型\\n\\n#### 核心实体\\n\\n##### 用户模型 (User)\\n```typescript\\ninterface User {\\n  id?: string\\n  username: string\\n  nickname?: string\\n  avatar?: string\\n  status: number\\n  // ... 其他字段\\n}\\n```\\n\\n##### 故事模型 (Story)\\n```typescript\\ninterface Story {\\n  id?: number\\n  title: string\\n  description?: string\\n  authorName: string\\n  coverUrl?: string\\n  categoryId: number\\n  wordCount: number\\n  chapterCount: number\\n  // ... 其他字段\\n}\\n```\\n\\n##### 章节模型 (Chapter)\\n```typescript\\ninterface Chapter {\\n  id?: number\\n  storyId: number\\n  title: string\\n  content?: string\\n  chapterIndex: number\\n  wordCount: number\\n  // ... 其他字段\\n}\\n```\\n\\n\\n\\n\\n\\n## 总结\\n\\n目前我们上架的作品也已经达到了五个。\\n\\n![image-20250705142201794](assets/image-20250705142201794.png)\\n\\n[关于青蓝逐码组织](https://link.juejin.cn/?target=https%3A%2F%2Fwww.qinglanzhuma.cn%2F)\\n\\n如果你兴趣想要了解更多的鸿**蒙应用开发细节和最新资讯**，**甚至你想要做出一款属于自己的应用**！欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n![image-20250611211811768](assets/image-20250611211811768.png)"}'),y={name:"鸿蒙开发技巧/第五款 HarmonyOS 上架作品 奇趣故事匣 来了/第五款 HarmonyOS 上架作品 奇趣故事匣 来了.md"};function F(q,a,_,S,A,f){return n(),i("div",null,[...a[0]||(a[0]=[t("",96)])])}const E=s(y,[["render",F]]);export{C as __pageData,E as default};
